District comparison of kg/day


Code
big_ilce &lt;- feeding |&gt;
  count(ilce) |&gt;
  filter(n &gt;= 50) |&gt;
  pull(ilce)

feeding_sub &lt;- feeding |&gt;
  filter(ilce %in% big_ilce, !is.na(mama_kg)) |&gt;
  mutate(ilce = stats::reorder(factor(ilce), mama_kg, FUN = median, na.rm = TRUE))

ggplot(feeding_sub, aes(x = ilce, y = mama_kg)) +
  geom_boxplot(outlier.alpha = 0.3, fill = "#F18F01") +
  coord_flip() +
  scale_y_continuous(labels = label_number(suffix = " kg")) +
  labs(x = NULL, y = "Average dry food (kg/day)") +
  theme_minimal(base_size = 12)








Figure 5: Distribution of kg/day by district (districts with ≥ 50 records across the year).

Top districts over time
How does the monthly kg total vary across the top five districts (by record count)?


Code
top5 &lt;- feeding |&gt;
  count(ilce, sort = TRUE) |&gt;
  slice_head(n = 5) |&gt;
  pull(ilce)

feeding_top &lt;- feeding |&gt;
  filter(ilce %in% top5, !is.na(tarih)) |&gt;
  mutate(month_start = lubridate::floor_date(tarih, "month")) |&gt;
  group_by(ilce, month_start) |&gt;
  summarise(total_kg = sum(mama_kg, na.rm = TRUE), .groups = "drop")

ggplot(feeding_top, aes(month_start, total_kg, color = ilce)) +
  geom_line(linewidth = 0.9) +
  geom_point(size = 1.8) +
  scale_x_date(date_labels = "%b %Y", date_breaks = "1 month") +
  scale_y_continuous(labels = label_number(suffix = " kg", big.mark = ",")) +
  labs(x = NULL, y = "Total reported kg / month", color = "İlçe") +
  theme_minimal(base_size = 12) +
  theme(
    axis.text.x = element_text(angle = 35, hjust = 1),
    legend.position = "bottom"
  )








Figure 6: Monthly total kg of dry food for the five most-reported districts.
